const I18N = { en: {}, de: {} };
I18N_ROWS.forEach(([hu, en, de]) => { I18N.en[hu] = en; I18N.de[hu] = de; });
function tr(key, vars) {
  let s = (state.lang !== 'hu' && I18N[state.lang]?.[key]) || key;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => vars[k] ?? m);
  return s;
}
const LOC = () => ({ hu: 'hu-HU', en: 'en-GB', de: 'de-DE' })[state.lang] || 'hu-HU';
const TLANG = () => ({ hu: 'hu-HU', en: 'en-US', de: 'de-DE' })[state.lang] || 'hu-HU';
function applyStaticI18n() {
  document.documentElement.lang = state.lang;
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = tr(el.dataset.i18n); });
  document.querySelectorAll('[data-i18n-aria]').forEach(el => el.setAttribute('aria-label', tr(el.dataset.i18nAria)));
  document.querySelectorAll('[data-i18n-title]').forEach(el => el.setAttribute('title', tr(el.dataset.i18nTitle)));
}
